# ---- source registry: every url used by any price row
SRC={}
def sid(url,name,year=None,typ=None):
    if url not in SRC: SRC[url]={'id':'S%02d'%(len(SRC)+1),'name':name,'url':url,'year':year,'type':typ}
    return SRC[url]['id']
GA='https://muqawil.org/public/publications/11c2ebd62a7f0e739cc71a1819af8bf2990cc7b6.pdf'
sid(GA,'الهيئة السعودية للمقاولين: تقرير أسعار مواد البناء، يوليو 2026 (بيانات الهيئة العامة للإحصاء)',2026,'official')
def rows(code): return [x for x in civil+mep if x.get('code')==code]
def srcs_of(code,filt=None):
    out=[]
    for x in rows(code):
        if filt and not filt(x): continue
        out.append(sid(x['source_url'],x['source_name'],x.get('year'),x.get('source_type')))
    return sorted(set(out))
M={x['material_ar']:x['price_sar'] for x in mat if x['period']=='2026-07'}
RB=M['حديد تسليح وطني 12 ملم']/1000; CS=M['خرسانة جاهزة مقاومة 350 كجم/سم2']; CN=M['خرسانة جاهزة عادية 350 كجم/سم2']; C250=M['خرسانة جاهزة عادية 250 كجم/سم2']
OHP=0.15
ASM={'F':(30,45),'fix':(400,600),'P':(40,70)}
def rc(c,r,a,cname):
    vals=[]
    for i in (0,1):
        F=ASM['F'][i];fx=ASM['fix'][i];P=ASM['P'][i]
        v=(c + r*RB*1.05 + r/1000*fx + a*F + P)*(1+OHP);vals.append(round(v/10)*10)
    comp=[('خرسانة جاهزة '+cname,'%.2f ريال/م³'%c,'S01'),('حديد التسليح','%d كجم/م³ × %.2f ريال/كجم + 5%% هدر'%(r,RB),'S01'),('تشكيل وتركيب الحديد','%d إلى %d ريال/طن'%ASM['fix'],'افتراض'),('الشدات','%.1f م²/م³ × %d إلى %d ريال/م²'%(a,ASM['F'][0],ASM['F'][1]),'افتراض'),('الصب والهز والضخ والمعالجة','%d إلى %d ريال/م³'%ASM['P'],'افتراض'),('مصاريف عامة وربح','15%','افتراض')]
    return vals,comp
P={}
def put(code,low,typ,high,basis,method,src,note='',conf='medium',comp=None,unit=None):
    P[code]=dict(low=low,typ=typ,high=high,basis=basis,method=method,sources=src,note=note,confidence=conf)
    if comp: P[code]['analysis']=[{'part':a,'value':b,'src':c} for a,b,c in comp]
    if unit: P[code]['unit_price']=unit
